function acceptStatus(data){const previous=state.status;state.status=data;if(previous&&(previous.gamePath!==data.gamePath||previous.configStamp!==data.configStamp)){state.buddyPreview=null;state.buddyEpoch++;if(previous.gamePath!==data.gamePath){state.buddyResult=null;state.buddyInstall=null;}renderBuddy();}if(JSON.stringify(previous?.buddyRecovery)!==JSON.stringify(data.buddyRecovery))renderBuddy();$('#game-state').textContent=data.running?'游戏正在运行':data.validGame?'已找到游戏':'未选择游戏';$('#connection').textContent=preview?'界面测试预览':data.running?'游戏运行中':'原生连接';document.documentElement.classList.toggle('light',data.theme==='light');$('#theme').textContent=data.theme==='light'?'黑金主题':'浅蓝主题';if(previous&&previous.configStamp!==data.configStamp){if(state.saveDirty&&state.route==='saves')notify('外部配置状态已变化，未保存的存档模组顺序已保留。保存时将校验原始快照；若存档发生变化，请重新读取。');for(const name of ['memory','settings']){if(state[name+'Dirty']){state[name+'Conflict']=true;if(state.route===name){notify('外部配置已变化，未保存编辑已保留。请重新读取后再保存。');const save=$('[data-save-'+name+']');if(save)save.disabled=true;}}else {state[name]=null;if(state.route===name)load(name);}}if(state.route==='shaders'){state.shaders=null;load('shaders');}}task(data.task||{active:false});if(!previous||['home','components'].includes(state.route)&&JSON.stringify({validGame:previous.validGame,running:previous.running,components:previous.components,launch:state.route==='home'?previous.launch:null,hardware:state.route==='home'?previous.hardware:null})!==JSON.stringify({validGame:data.validGame,running:data.running,components:data.components,launch:state.route==='home'?data.launch:null,hardware:state.route==='home'?data.hardware:null}))render();}
